            self.crate_minimum = s.get_int("CrateMinimum").unwrap_or(self.crate_minimum);
            self.crate_maximum = s.get_int("CrateMaximum").unwrap_or(self.crate_maximum);
            self.is_scatter = s.get_bool("PlayerScatter").unwrap_or(self.is_scatter);
            self.is_smart_defense = s
