            self.is_auto_crush = s.get_bool("PlayerAutoCrush").unwrap_or(self.is_auto_crush);
            self.is_named = s.get_bool("NamedCivilians").unwrap_or(self.is_named);
            self.is_t_growth = s.get_bool("OreGrows").unwrap_or(self.is_t_growth);
            self.is_t_spread = s.get_bool("OreSpreads").unwrap_or(self.is_t_spread);
            self.is_mine_aware = s.get_bool("MineAware").unwrap_or(self.is_mine_aware);
